"""Generates src/ui/48-decay-icrp.js from radioactivedecay 0.6.1 (dataset icrp107_ame2020_nubase2020: ICRP Publication 107 decay data with
half-lives updated to AME2020/NUBASE2020; 1512 nuclides including isomers, with branching fractions and daughters, isomer-aware)."""
import numpy as np, json, glob, re
from math import isinf
f = glob.glob('/tmp/pk/x_radioactivedecay*/radioactivedecay/icrp107_ame2020_nubase2020/decay_data.npz')[0]
d = np.load(f, allow_pickle=True)
UNIT = {'y': 365.2422 * 86400, 'd': 86400, 'h': 3600, 'm': 60, 's': 1, 'ms': 1e-3, 'μs': 1e-6}
SYM = ['n','H','He','Li','Be','B','C','N','O','F','Ne','Na','Mg','Al','Si','P','S','Cl','Ar','K','Ca','Sc','Ti','V','Cr','Mn','Fe','Co','Ni','Cu','Zn','Ga','Ge','As','Se','Br','Kr','Rb','Sr','Y','Zr','Nb','Mo','Tc','Ru','Rh','Pd','Ag','Cd','In','Sn','Sb','Te','I','Xe','Cs','Ba','La','Ce','Pr','Nd','Pm','Sm','Eu','Gd','Tb','Dy','Ho','Er','Tm','Yb','Lu','Hf','Ta','W','Re','Os','Ir','Pt','Au','Hg','Tl','Pb','Bi','Po','At','Rn','Fr','Ra','Ac','Th','Pa','U','Np','Pu','Am','Cm','Bk','Cf','Es','Fm','Md','No','Lr','Rf','Db','Sg','Bh','Hs','Mt','Ds']
def nid(name):
    m = re.fullmatch(r'([A-Z][a-z]?)-(\d+)([mn]?)', str(name)); Z = SYM.index(m.group(1)); iso = {'': 0, 'm': 1, 'n': 2}[m.group(3)]
    return (Z * 1000 + int(m.group(2))) * 10 + iso
MODE = {'β-': 'B-', 'β+ & EC': 'EC', 'EC': 'EC', 'α': 'A', 'IT': 'IT', 'SF': 'SF'}
out = {}; stable = []
for i, n in enumerate(d['nuclides']):
    hl, u, _ = d['hldata'][i]; pr = list(d['progeny'][i])
    if not pr or isinf(float(hl)): stable.append(nid(n)); continue
    br = []
    for p, f_, m in zip(pr, d['bfs'][i], d['modes'][i]):
        br.append('%d:%s:%s' % (0 if p == 'SF' else nid(p), ('%.6g' % f_), MODE[m]))
    out[nid(n)] = [float('%.7g' % (float(hl) * UNIT[u])), ';'.join(br)]
js = '/* ====== internal decay data with isomers (generated by tools_gen_icrp.py from the Python package radioactivedecay 0.6.1, dataset icrp107_ame2020_nubase2020: ICRP Publication 107 decay data, half-lives of AME2020/NUBASE2020) ======\n   DK_ICRP[id] = [T½ (s), "daughter id:fraction:mode;…"]  (id = 10·(1000 Z + A) + isomer; daughter 0 = spontaneous fission);  DK_ICRP_STABLE = stable nuclides of the dataset */\n'
js += 'const DK_ICRP = ' + json.dumps(out, separators=(',', ':')) + ';\nconst DK_ICRP_STABLE = new Set(' + json.dumps(stable, separators=(',', ':')) + ');\n'
open('src/ui/48-decay-icrp.js', 'w').write(js); print(len(out), len(stable), len(js))
